def transform(g):
    h,w=len(g),len(g[0])
    out=[row[:] for row in g]
    bg=g[0][0]
    # collect diagonal lines (slope +1: r-c const; slope -1: r+c const)
    for key in ([(r-c,'d') for r in range(h) for c in range(w)],):
        pass
    lines={}
    for r in range(h):
        for c in range(w):
            if g[r][c]!=bg:
                lines.setdefault(('d',r-c),[]).append((r,c))
                lines.setdefault(('a',r+c),[]).append((r,c))
    for k,cells in lines.items():
        if len(cells)<3: continue
        # segments by color
        from collections import defaultdict
        segs=defaultdict(list)
        for r,c in cells: segs[g[r][c]].append((r,c))
        for col,pts in segs.items():
            pts.sort()
            for (r,c) in pts:
                dr,dc=(1,1) if k[0]=='d' else (1,-1)
                for s in (1,-1):
                    rr,cc=r+s*dr,c+s*dc
                    while 0<=rr<h and 0<=cc<w and out[rr][cc]==bg:
                        out[rr][cc]=col
                        rr+=s*dr; cc+=s*dc
    return out

